// Event handling
/*
// 'data', 'variables', 'options', 'utils', and 'event' are passed as arguments

try {
  const { type: eventType, data: eventData } = event;
  const { timeZone, dayjs, locationService, getTemplateSrv } = utils;

  switch (eventType) {
    case 'click':
      console.log('Click event:', eventData.points);
      break;
    case 'select':
      console.log('Selection event:', eventData.range);
      break;
    case 'zoom':
      console.log('Zoom event:', eventData);
      break;
    default:
      console.log('Unhandled event type:', eventType, eventData);
  }

  console.log('Current time zone:', timeZone);
  console.log('From time:', dayjs(variables.__from).format());
  console.log('To time:', dayjs(variables.__to).format());

  // Example of using locationService
  // locationService.partial({ 'var-example': 'test' }, true);

} catch (error) {
  console.error('Error in onclick handler:', error);
}
*/

options.script:
const traces = [];
const annotations = [];
const shapes = [];

const CLUSTER_MS = 5000;
const AY_STEP = 44;
const AX_SIDE = 130;

data.series.forEach((s) => {
  const time = s.fields.find((f) => f.type === 'time');
  const value = s.fields.find((f) => f.type === 'number');
  if (!time || !value) return;

  const labels = value.labels || s.labels || {};
  const metric = s.name || value.name || '';
  const isEvent =
    s.refId === 'D' ||
    metric.includes('aos_annotations') ||
    metric.includes('app_event') ||
    labels.text != null ||
    labels.event != null ||
    labels.msg != null;

  const xs = time.values.toArray();
  const ys = value.values.toArray();

  if (isEvent) {
    for (let i = 0; i < xs.length; i++) {
      if (ys[i] == null) continue;
      if (i > 0 && ys[i - 1] != null && ys[i] === ys[i - 1]) continue;

      const full =
        labels.text ||
        labels.msg ||
        labels.event ||
        (metric.match(/text="([^"]+)"/) || [])[1] ||
        (metric.match(/msg="([^"]+)"/) || [])[1] ||
        'event';

      const short = full.length > 36 ? full.slice(0, 34) + '…' : full;

      annotations.push({
        x: xs[i],
        y: 1,
        xref: 'x',
        yref: 'paper',
        text: short,
        hovertext: full,
        showarrow: true,
        arrowhead: 2,
        ax: 0,
        ay: 30,
        axref: 'pixel',
        ayref: 'pixel',
        xanchor: 'center',
        yanchor: 'top',
        bgcolor: 'rgba(0,0,0,0.85)',
        bordercolor: 'orange',
        borderwidth: 1,
        font: { color: 'white', size: 11 },
        captureevents: true,
        cliponaxis: false,
        _x: xs[i],
      });
    }
    return;
  }

  const name =
    s.refId === 'A' ? 'RAM used' :
    s.refId === 'B' ? 'Swap used' :
    s.refId === 'C' ? ('PSS ' + (labels.groupname || metric || 'aos')) :
    labels.groupname || labels.instance || metric || 'memory';

  traces.push({
    type: 'scatter',
    mode: 'lines',
    name: name,
    x: xs,
    y: ys,
  });
});

annotations.sort((a, b) => a._x - b._x);

let cluster = [];
const flush = () => {
  if (!cluster.length) return;

  shapes.push({
    type: 'line',
    x0: cluster[0]._x,
    x1: cluster[0]._x,
    xref: 'x',
    y0: 0,
    y1: 1,
    yref: 'paper',
    line: { color: 'orange', width: 1, dash: 'dot' },
  });

  cluster.forEach((ann, idx) => {
    // positive ay = into the chart (not off the top)
    // 2 columns: even left, odd right
    const row = Math.floor(idx / 2);
    ann.ay = 24 + row * AY_STEP;
    ann.ax = (idx % 2 === 0) ? -AX_SIDE : AX_SIDE;
    ann.xanchor = (idx % 2 === 0) ? 'right' : 'left';
    delete ann._x;
  });
  cluster = [];
};

for (const ann of annotations) {
  if (cluster.length && ann._x - cluster[0]._x > CLUSTER_MS) flush();
  cluster.push(ann);
}
flush();

return {
  data: traces,
  layout: {
    annotations,
    shapes,
    margin: { t: 30, r: 160, l: 160 },
  },
};

